css:
.agbssim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20242e;
    background: linear-gradient(165deg, #f4f1ea 0%, #eae4d6 100%);
    border-radius: 18px;
}

.agbssim-container * {
    box-sizing: border-box;
}

.agbssim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #14213d 0%, #1f3a5f 55%, #2c5077 100%);
    color: #f7f4ec;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(20, 33, 61, 0.32);
    border-bottom: 4px solid #c8a24a;
}

.agbssim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #ffffff;
}

.agbssim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0dca8;
    background: rgba(200, 162, 74, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.agbssim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3ddd0;
}

.agbssim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3a52;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.agbssim-period-counter #currentDay,
.agbssim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14213d;
}

.agbssim-round-name {
    background: #14213d;
    color: #f0dca8;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.agbssim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a2b1f;
    background: #f4ddd6;
    padding: 4px 12px;
    border-radius: 999px;
}

.agbssim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.agbssim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0d9c8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
    border-top: 4px solid #2c5077;
}

.agbssim-card-coherence { border-top-color: #1f6f5c; }
.agbssim-card-enrolment { border-top-color: #2c5077; }
.agbssim-card-utilization { border-top-color: #c8a24a; }
.agbssim-card-budget { border-top-color: #6a4a8a; }

.agbssim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7385;
}

.agbssim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14213d;
}

.agbssim-card-coherence .agbssim-value { color: #1f6f5c; }
.agbssim-card-enrolment .agbssim-value { color: #2c5077; }
.agbssim-card-utilization .agbssim-value { color: #b07f1a; }
.agbssim-card-budget .agbssim-value { color: #6a4a8a; }

.agbssim-sublabel {
    font-size: 0.76rem;
    color: #7c8295;
    line-height: 1.35;
}

.agbssim-coherence-fail .agbssim-value { color: #c0392b; }
.agbssim-coherence-target .agbssim-value { color: #1f6f5c; }

.agbssim-enrolment-target .agbssim-value { color: #1f6f5c; }
.agbssim-enrolment-short .agbssim-value { color: #b07f1a; }

.agbssim-utilization-danger .agbssim-value { color: #c0392b; }
.agbssim-utilization-danger { border-top-color: #c0392b; }

.agbssim-budget-over .agbssim-value { color: #c0392b; }
.agbssim-budget-over { border-top-color: #c0392b; }

.agbssim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14213d;
    color: #f0e9da;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.agbssim-budget-bar #budgetBarDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0dca8;
}

.agbssim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c8a24a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.05);
}

.agbssim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.agbssim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14213d;
    margin-bottom: 6px;
}

.agbssim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #36404f;
}

.agbssim-briefing-text strong { color: #1f6f5c; }
.agbssim-briefing-text em { color: #8a2b1f; font-style: italic; }

.agbssim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0d9c8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.06);
}

.agbssim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14213d;
    border-bottom: 2px solid #ece6d8;
    padding-bottom: 8px;
}

.agbssim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3346;
    margin: 14px 0 6px;
}

.agbssim-container select,
.agbssim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbbf9f;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf9f3;
    color: #20242e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.agbssim-container select:focus,
.agbssim-container input[type="number"]:focus {
    outline: none;
    border-color: #2c5077;
    box-shadow: 0 0 0 3px rgba(44, 80, 119, 0.16);
}

.agbssim-container select option {
    background-color: #ffffff;
    color: #20242e;
}

.agbssim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2c5077;
}

.agbssim-range-readout,
.agbssim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c5077;
    margin-top: 4px;
}

.agbssim-range-readout span:last-child,
.agbssim-alloc-readout span:nth-child(2) {
    color: #1f6f5c;
    font-weight: 800;
}

.agbssim-hint {
    font-size: 0.8rem;
    color: #7c8295;
    margin-top: 4px;
    line-height: 1.4;
}

.agbssim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.agbssim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f2e8;
    border: 1px solid #e4dcc7;
    border-radius: 9px;
    padding: 8px 12px;
}

.agbssim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2a3346;
}

.agbssim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.agbssim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.agbssim-container .btn-primary {
    background: linear-gradient(135deg, #14213d 0%, #2c5077 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(20, 33, 61, 0.28);
}

.agbssim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.agbssim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbbf9f;
    color: #6c7385;
}

.agbssim-coach {
    background: linear-gradient(135deg, #14213d 0%, #243b5c 100%);
    color: #eef0f4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 33, 61, 0.24);
    border-left: 5px solid #c8a24a;
}

.agbssim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0dca8;
    margin-bottom: 8px;
}

.agbssim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.agbssim-coach-body strong { color: #f0dca8; }
.agbssim-coach-body em { color: #f3b9a8; font-style: italic; }

.agbssim-history,
.agbssim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0d9c8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.06);
}

.agbssim-history h3,
.agbssim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14213d;
}

.agbssim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3346;
}

.agbssim-container table#usfHistoryTable th {
    background: #f1ece0;
    color: #14213d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d6bf;
}

.agbssim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece2;
}

.agbssim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.agbssim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .agbssim-container {
        padding: 14px;
    }
    .agbssim-header h1 {
        font-size: 1.7rem;
    }
    .agbssim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .agbssim-value {
        font-size: 2rem;
    }
    .agbssim-clock {
        margin-left: 0;
    }
    .agbssim-period-counter {
        font-size: 0.88rem;
    }
    .agbssim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .agbssim-alloc-row {
        flex-wrap: wrap;
    }
    .agbssim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .agbssim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.agbssim-completion { padding: 8px 4px 4px; }
.agbssim-cm-head { text-align: center; margin-bottom: 16px; }
.agbssim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f9e83; }
.agbssim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #7fc9b6; }
.agbssim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #ffffff; }
.agbssim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.agbssim-cm-yes { background: rgba(31,111,92,0.2); color: #4fc4a3; border: 1px solid rgba(31,111,92,0.6); }
.agbssim-cm-no { background: rgba(192,57,43,0.16); color: #e88b81; border: 1px solid rgba(192,57,43,0.55); }
.agbssim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.agbssim-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(44,80,119,0.16); border: 1px solid rgba(44,80,119,0.34); border-radius: 10px; padding: 10px 8px; text-align: center; }
.agbssim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #6a9bd0; }
.agbssim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #b3bccd; text-transform: uppercase; letter-spacing: 0.03em; }
.agbssim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #ffffff; }
.agbssim-cm-insights { margin: 0; padding-left: 20px; }
.agbssim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #d7dde8; }

