(function() {
    'use strict';

    class ArchitectAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Global Program Architect`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_COHERENCE = 45;       // out of 100
            this.COHERENCE_FLOOR = 75;       // accreditation-safe floor
            this.COHERENCE_EXCELLENT = 90;   // identical-curriculum ceiling
            this.START_ENROLMENT = 95;       // unpositioned demand
            this.TARGET_ENROLMENT = 120;     // break-even at EUR 24,000 tuition
            this.START_UTILIZATION = 88;     // burnout danger line
            this.UTIL_DANGER = 88;           // sustainable below this
            this.BUDGET_CAP = 2.40;          // EUR 2.4M, in millions (hard cap)
            this.SOFT_BUDGET = 1.50;         // EUR 1.5M — spend beyond this crowds out marketing
            this.FTE_NEED = 9.0;             // FTE-equivalents required
            this.CORE_FACULTY = 6.0;         // qualified core faculty available
            this.TUITION = 24000;            // EUR year-one tuition

            // Concept truths.
            this.TRUE_BINDING = `faculty`;   // the hardest, design-shaping constraint
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    coherence: this.START_COHERENCE,
                    enrolment: this.START_ENROLMENT,
                    utilization: this.START_UTILIZATION,
                    budgetUsed: 0,
                    overBudget: false,
                    burnout: false,
                    accreditationReady: false,
                    coherenceHistory: [this.START_COHERENCE],
                    enrolmentHistory: [this.START_ENROLMENT],
                    utilizationHistory: [this.START_UTILIZATION],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    campus: `strong`,
                    binding: `faculty`,
                    cannibal: 60,
                    core: 60,
                    assess: `spine`,
                    position: `relevance`,
                    coreFac: 4.5,
                    hire: 2.0,
                    visit: 1.5,
                    online: 1.0,
                    week: `hybrid`,
                    caseModel: `evidence`,
                    phasing: `staged`,
                    pitch: `honest`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const campus = document.getElementById(`campusInput`);
                const binding = document.getElementById(`bindingInput`);
                const can = document.getElementById(`cannibalInput`);
                if (campus) decisions.campus = campus.value;
                if (binding) decisions.binding = binding.value;
                if (can) decisions.cannibal = parseInt(can.value, 10);
                if (!Number.isFinite(decisions.cannibal) || decisions.cannibal < 0 || decisions.cannibal > 100) {
                    warn(`warn_cannibal_range`); return false;
                }
            } else if (round === 2) {
                const core = document.getElementById(`coreInput`);
                const assess = document.getElementById(`assessInput`);
                const pos = document.getElementById(`positionInput`);
                if (core) decisions.core = parseFloat(core.value);
                if (assess) decisions.assess = assess.value;
                if (pos) decisions.position = pos.value;
                if (!Number.isFinite(decisions.core) || decisions.core < 0 || decisions.core > 100) {
                    warn(`warn_core_range`); return false;
                }
            } else if (round === 3) {
                const cf = document.getElementById(`coreFacInput`);
                const hi = document.getElementById(`hireInput`);
                const vi = document.getElementById(`visitInput`);
                const on = document.getElementById(`onlineInput`);
                const wk = document.getElementById(`weekInput`);
                if (cf) decisions.coreFac = parseFloat(cf.value);
                if (hi) decisions.hire = parseFloat(hi.value);
                if (vi) decisions.visit = parseFloat(vi.value);
                if (on) decisions.online = parseFloat(on.value);
                if (wk) decisions.week = wk.value;
                const parts = [decisions.coreFac, decisions.hire, decisions.visit, decisions.online];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_fte_negative`); return false;
                }
                if (decisions.coreFac > this.CORE_FACULTY + 0.001) {
                    warn(`warn_fte_corecap`); return false;
                }
                const total = decisions.coreFac + decisions.hire + decisions.visit + decisions.online;
                if (total < this.FTE_NEED - 0.001) {
                    warn(`warn_fte_total`); return false;
                }
            } else if (round === 4) {
                const cm = document.getElementById(`caseInput`);
                const ph = document.getElementById(`phasingInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (cm) decisions.caseModel = cm.value;
                if (ph) decisions.phasing = ph.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas. coherence/enrolment move on their own deltas; utilization is RESET
            // each operational round from the faculty mix; budget accrues spend (EUR millions).
            let coherenceDelta = 0, enrolmentDelta = 0, utilizationDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Lead-campus choice: balance faculty base, multi-market relevance and
                // accreditation-regime complexity. "Strong" = the deliberate, defensible mix.
                switch (d.campus) {
                    case `strong`: coherenceDelta += 5; enrolmentDelta += 6; utilizationDelta -= 1; coachKey = `coach_r1_campus_strong`; break;
                    case `home`: coherenceDelta += 6; enrolmentDelta -= 6; coachKey = `coach_r1_campus_home`; break;
                    case `spread`: coherenceDelta -= 6; enrolmentDelta += 3; utilizationDelta += 2; coachKey = `coach_r1_campus_spread`; break;
                    case `all`: coherenceDelta -= 12; enrolmentDelta += 2; utilizationDelta += 6; coachKey = `coach_r1_campus_all`; break;
                }

                // Naming the binding constraint. Faculty is the hardest, design-shaping one.
                if (d.binding === this.TRUE_BINDING) {
                    coherenceDelta += 5; enrolmentDelta += 2;
                    coachKey = (d.campus === `strong`) ? `coach_r1_binding_sharp` : `coach_r1_binding_faculty`;
                } else if (d.binding === `coherence` || d.binding === `budget`) {
                    coherenceDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r1_binding_partial` : coachKey;
                } else {
                    coherenceDelta -= 12; enrolmentDelta -= 6; coachKey = `coach_r1_binding_none`;
                }

                // Portfolio rigour: modelling cannibalization protects NET enrolment.
                // Ignoring it ~ the concept's 30-student cannibalization of the existing masters.
                if (d.cannibal >= 60) { enrolmentDelta += 5; coherenceDelta += 2; }
                else if (d.cannibal <= 25) { enrolmentDelta -= 22; coachKey = `coach_r1_standalone`; }

                summaryKey = (d.campus === `strong` && d.binding === this.TRUE_BINDING && d.cannibal >= 60) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Global/local split — the integration-vs-responsiveness tension.
                // Sweet spot ~55-70% shared core: coherent enough to accredit, relevant enough to enrol.
                const core = d.core;
                if (core >= 55 && core <= 70) {
                    coherenceDelta += 10; enrolmentDelta += 5; coachKey = `coach_r2_balanced`;
                } else if (core > 70 && core <= 85) {
                    coherenceDelta += 11; enrolmentDelta -= 8; coachKey = `coach_r2_high`;
                } else if (core > 85) {
                    coherenceDelta += 13; enrolmentDelta -= 22; coachKey = `coach_r2_standardize`;
                } else if (core >= 40 && core < 55) {
                    coherenceDelta += 5; enrolmentDelta += 2; coachKey = `coach_r2_lowish`;
                } else {
                    coherenceDelta -= 12; coachKey = `coach_r2_fragment`;
                }

                // Assessment-equivalence model — what the accreditors actually audit.
                switch (d.assess) {
                    case `spine`: coherenceDelta += 6; enrolmentDelta += 2; coachKey = (core >= 55 && core <= 70) ? `coach_r2_spine_sharp` : coachKey; break;
                    case `identical`: coherenceDelta += 3; enrolmentDelta -= 8; coachKey = `coach_r2_identical`; break;
                    case `local`: coherenceDelta -= 14; coachKey = `coach_r2_localassess`; break;
                }

                // Positioning to lift demand toward 120.
                switch (d.position) {
                    case `relevance`: enrolmentDelta += 9; coherenceDelta += 2; break;
                    case `prestige`: enrolmentDelta += 2; break;
                    case `underprice`: enrolmentDelta += 13; coherenceDelta -= 8; coachKey = `coach_r2_underprice`; break;
                }

                summaryKey = (core >= 55 && core <= 70 && d.assess === `spine` && d.position === `relevance`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Faculty allocation: utilization is recomputed from the EXISTING-core load.
                // Loading all 6 core faculty pushes utilization toward burnout; hiring,
                // visiting and online lift the load OFF the core faculty.
                const totalFte = d.coreFac + d.hire + d.visit + d.online;
                // Each existing-core FTE deployed adds ~8 utilization points over a 40% floor.
                let util = 40 + d.coreFac * 8;
                ds.utilization = Math.max(40, Math.min(100, Math.round(util)));

                if (ds.utilization >= 95) { coherenceDelta -= 8; enrolmentDelta -= 8; coachKey = `coach_r3_burnout`; }
                else if (ds.utilization >= this.UTIL_DANGER) { coherenceDelta -= 3; enrolmentDelta -= 2; coachKey = `coach_r3_tight`; }
                else { coherenceDelta += 5; enrolmentDelta += 2; coachKey = `coach_r3_sustainable`; }

                // Coverage quality: visiting/online carry less continuity than hired/core.
                if (totalFte < this.FTE_NEED + 0.001) {
                    // Exactly meeting need is fine; thin online-heavy coverage dilutes the experience.
                    if (d.online >= 3) { coherenceDelta -= 6; coachKey = `coach_r3_onlineheavy`; }
                }

                // Faculty spend (EUR millions).
                spend += (d.hire * 0.220) + (d.visit * 0.090) + (d.online * 0.040);

                // International Week format — cost-aware experience design. The full
                // residential week consumes the marketing budget, so net enrolment FALLS.
                switch (d.week) {
                    case `hybrid`: spend += 0.260; coherenceDelta += 5; enrolmentDelta += 7; coachKey = (ds.utilization < this.UTIL_DANGER) ? `coach_r3_hybrid` : coachKey; break;
                    case `hub`: spend += 0.180; coherenceDelta += 4; enrolmentDelta += 5; break;
                    case `residential`: spend += 0.480; coherenceDelta += 4; enrolmentDelta -= 12; coachKey = `coach_r3_residential`; break;
                    case `virtual`: spend += 0.040; coherenceDelta -= 3; enrolmentDelta -= 8; coachKey = `coach_r3_virtual`; break;
                }

                const sustainable = ds.utilization < this.UTIL_DANGER;
                summaryKey = (sustainable && (d.week === `hybrid` || d.week === `hub`)) ? `sum_r3_good` : (ds.utilization >= 95 ? `sum_r3_burnout` : `sum_r3_weak`);
            } else if (round === 4) {
                // Accreditation-readiness case.
                switch (d.caseModel) {
                    case `evidence`: coherenceDelta += 6; enrolmentDelta += 2; coachKey = `coach_r4_evidence`; break;
                    case `narrative`: coherenceDelta += 2; coachKey = `coach_r4_narrative`; break;
                    case `thin`: coherenceDelta -= 10; coachKey = `coach_r4_thin`; break;
                }

                // Phasing the remaining campuses against the hiring runway.
                switch (d.phasing) {
                    case `staged`: coherenceDelta += 4; enrolmentDelta += 4; break;
                    case `rush`: coherenceDelta -= 8; enrolmentDelta += 2; utilizationDelta += 5; coachKey = `coach_r4_rush`; break;
                    case `freeze`: enrolmentDelta -= 4; coachKey = `coach_r4_freeze`; break;
                }

                // The pitch to the Dean and review panel.
                switch (d.pitch) {
                    case `honest`: coherenceDelta += 5; enrolmentDelta += 3; coachKey = (d.caseModel === `evidence` && d.phasing === `staged`) ? `coach_r4_honest` : coachKey; break;
                    case `overclaim`: enrolmentDelta += 8; coherenceDelta -= 12; coachKey = `coach_r4_overclaim`; break;
                    case `defer`: coherenceDelta -= 8; coachKey = `coach_r4_defer`; break;
                }

                // Conviction nudges coherence (the steady defence of a real design).
                coherenceDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.caseModel === `evidence` && d.phasing === `staged` && d.pitch === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply utilization changes that are NOT a Round-3 reset (e.g. R1/R4 nudges).
            if (round !== 3 && utilizationDelta !== 0) {
                ds.utilization = Math.max(40, Math.min(100, ds.utilization + utilizationDelta));
            }

            // Coherence and enrolment.
            ds.coherence = Math.max(0, Math.min(100, ds.coherence + coherenceDelta));
            ds.enrolment = Math.max(0, Math.round(ds.enrolment + enrolmentDelta));

            // Budget accrual (EUR millions). Overspend is flagged, not silently capped.
            const budgetBefore = ds.budgetUsed;
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 1000) / 1000;
            if (ds.budgetUsed > this.BUDGET_CAP + 0.0001) ds.overBudget = true;

            // Marketing crowd-out: spend that carries cumulative budget above the soft
            // threshold eats the marketing budget, so net enrolment falls even while the
            // hard cap is not yet breached. Charged on the marginal spend ABOVE the
            // threshold this round, so it bites once (in the operational round) and is
            // not re-applied in later, spend-free rounds.
            const overSoftThisRound = Math.max(0, ds.budgetUsed - Math.max(budgetBefore, this.SOFT_BUDGET));
            if (overSoftThisRound > 0) {
                const crowd = Math.min(20, Math.round(overSoftThisRound * 25));
                ds.enrolment = Math.max(0, ds.enrolment - crowd);
            }

            // Burnout flag once utilization crosses the danger line on the operational round.
            if (ds.utilization >= 95) ds.burnout = true;

            ds.coherenceHistory.push(Math.round(ds.coherence));
            ds.enrolmentHistory.push(Math.round(ds.enrolment));
            ds.utilizationHistory.push(Math.round(ds.utilization));

            if (round === this.ROUNDS.length) {
                ds.accreditationReady = (ds.coherence >= this.COHERENCE_FLOOR && ds.enrolment >= this.TARGET_ENROLMENT && ds.utilization < this.UTIL_DANGER && !ds.overBudget);
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                coherence: Math.round(ds.coherence),
                coherenceDelta: Math.round(coherenceDelta),
                enrolment: Math.round(ds.enrolment),
                enrolmentDelta: Math.round(enrolmentDelta),
                utilization: Math.round(ds.utilization),
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

