        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula (incl. burnout + budget penalties) copied VERBATIM from
        // v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const coherence = Math.round(ds.coherence);
            const enrolment = Math.round(ds.enrolment);
            const utilization = Math.round(ds.utilization);
            const sustainable = utilization < this.UTIL_DANGER;
            const onBudget = !ds.overBudget;
            const softOverspend = ds.budgetUsed > this.SOFT_BUDGET;
            const cScore = Math.min(100, (coherence / this.COHERENCE_FLOOR) * 75);
            const eScore = Math.min(100, (enrolment / this.TARGET_ENROLMENT) * 80);
            const uScore = sustainable ? 90 : Math.max(0, 84 - (utilization - this.UTIL_DANGER) * 6);
            let composite = Math.round(cScore * 0.34 + eScore * 0.34 + uScore * 0.32);
            if (!onBudget) composite = Math.max(0, composite - 18);
            else if (softOverspend) composite = Math.max(0, composite - Math.min(15, Math.round((ds.budgetUsed - this.SOFT_BUDGET) * 18)));
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitCoherence && s.hitEnrolment && s.sustainable && s.onBudget);
            const badge = met
                ? `<span class="agbssim-cm-badge agbssim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="agbssim-cm-badge agbssim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const riskBadge = (s.onBudget === false)
                ? ` <span class="agbssim-cm-badge agbssim-cm-no">` + T(`cm_overbudget`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const budStr = (typeof s.budgetUsed === `number`) ? s.budgetUsed.toFixed(2) + `×` : String(s.budgetUsed || ``);
            const metrics = ``
                + `<div class="agbssim-cm-metric"><span class="agbssim-cm-mv">` + Math.round(s.coherence || 0) + `</span><span class="agbssim-cm-ml">` + T(`cm_m_coherence`) + `</span></div>`
                + `<div class="agbssim-cm-metric"><span class="agbssim-cm-mv">` + Math.round(s.enrolment || 0) + `</span><span class="agbssim-cm-ml">` + T(`cm_m_enrolment`) + `</span></div>`
                + `<div class="agbssim-cm-metric"><span class="agbssim-cm-mv">` + Math.round(s.utilization || 0) + `%</span><span class="agbssim-cm-ml">` + T(`cm_m_utilization`) + `</span></div>`
                + `<div class="agbssim-cm-metric"><span class="agbssim-cm-mv">` + budStr + `</span><span class="agbssim-cm-ml">` + T(`cm_m_budget`) + `</span></div>`;
            return ``
                + `<div class="agbssim-completion">`
                +   `<div class="agbssim-cm-head">`
                +     `<div class="agbssim-cm-score">` + score + `<span class="agbssim-cm-score-max">/100</span></div>`
                +     `<div class="agbssim-cm-grade">` + grade + ` ` + badge + riskBadge + `</div>`
                +   `</div>`
                +   `<div class="agbssim-cm-metrics">` + metrics + `</div>`
                +   `<div class="agbssim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="agbssim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const coherence = Math.round(ds.coherence);
            const enrolment = Math.round(ds.enrolment);
            const utilization = Math.round(ds.utilization);
            const budgetUsed = ds.budgetUsed;

            const hitCoherence = coherence >= this.COHERENCE_FLOOR;
            const hitEnrolment = enrolment >= this.TARGET_ENROLMENT;
            const sustainable = utilization < this.UTIL_DANGER;
            const onBudget = !ds.overBudget;
            // Genuine over-standardization = brand solved (high coherence) but the market
            // is clearly broken (enrolment well short), not merely a hair under target.
            const overStandardized = coherence >= this.COHERENCE_EXCELLENT && enrolment <= this.TARGET_ENROLMENT - 16;
            const softOverspend = ds.budgetUsed > this.SOFT_BUDGET;

            // Composite: coherence and enrolment normalised to their targets, utilization
            // inverted (lower is better). Sitting AT or above the burnout line is penalised
            // (baseline 84, not 90), and overspend costs marks even under the hard cap.
            const cScore = Math.min(100, (coherence / this.COHERENCE_FLOOR) * 75);
            const eScore = Math.min(100, (enrolment / this.TARGET_ENROLMENT) * 80);
            const uScore = sustainable ? 90 : Math.max(0, 84 - (utilization - this.UTIL_DANGER) * 6);
            let composite = Math.round(cScore * 0.34 + eScore * 0.34 + uScore * 0.32);
            if (!onBudget) composite = Math.max(0, composite - 18);
            else if (softOverspend) composite = Math.max(0, composite - Math.min(15, Math.round((ds.budgetUsed - this.SOFT_BUDGET) * 18)));

            let performanceKey = `grade_five`;
            if (hitCoherence && hitEnrolment && sustainable && onBudget && composite >= 80) performanceKey = `grade_one`;
            else if (hitCoherence && hitEnrolment && sustainable && onBudget) performanceKey = `grade_accred`;
            else if (overStandardized) performanceKey = `grade_overstd`;
            else if (hitCoherence && !sustainable) performanceKey = `grade_burnout`;
            else if (!onBudget) performanceKey = `grade_overbudget`;
            else if (hitCoherence) performanceKey = `grade_underenrol`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitCoherence && hitEnrolment && sustainable && onBudget) insights.push(window.mySimulation.t(`insight_coherent`));
            else if (overStandardized) insights.push(window.mySimulation.t(`insight_overstd`));
            else if (!hitCoherence) insights.push(window.mySimulation.t(`insight_fragmented`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!sustainable) insights.push(window.mySimulation.t(`insight_burnout`));
            if (!onBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (!hitEnrolment && hitCoherence) insights.push(window.mySimulation.t(`insight_underenrolled`));
            if (coherence >= this.COHERENCE_EXCELLENT && enrolment >= this.TARGET_ENROLMENT && sustainable) insights.push(window.mySimulation.t(`insight_exemplary`));

            return {
                coherence: coherence,
                enrolment: enrolment,
                utilization: utilization,
                budgetUsed: budgetUsed,
                accreditationReady: ds.accreditationReady,
                hitCoherence: hitCoherence,
                hitEnrolment: hitEnrolment,
                sustainable: sustainable,
                onBudget: onBudget,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_budget`);
            if (ds.utilization >= 95) return window.mySimulation.t(`hint_burnout`);
            if (ds.coherence >= this.COHERENCE_EXCELLENT && ds.enrolment < this.TARGET_ENROLMENT) return window.mySimulation.t(`hint_overstd`);
            if (state.currentPeriod >= 2 && ds.coherence < this.COHERENCE_FLOOR - 10) return window.mySimulation.t(`hint_coherence`);
            if (state.currentPeriod >= 3 && ds.enrolment < this.TARGET_ENROLMENT - 10) return window.mySimulation.t(`hint_enrolment`);
            if (ds.coherence >= this.COHERENCE_FLOOR && ds.enrolment >= this.TARGET_ENROLMENT && ds.utilization < this.UTIL_DANGER) return window.mySimulation.t(`hint_strong`);
            return null;
        }

